package com.afkingtoolkit;

import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.api.Skill;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AfkingToolkitConfig.GROUP)
public interface AfkingToolkitConfig extends Config
{
	String GROUP = "afkingtoolkit";

	enum AlertStyle
	{
		FLASH("Flash"), SOLID("Solid");

		private final String label;

		AlertStyle(String label) { this.label = label; }

		@Override
		public String toString() { return label; }
	}

	enum Trigger
	{
		OFF("Off"), ALWAYS("Always"), SUPPLIES("With supplies");

		private final String label;

		Trigger(String label) { this.label = label; }

		@Override
		public String toString() { return label; }
	}

	enum CannonTrigger
	{
		OFF("Off"), ANYWHERE("Anywhere"), NEARBY("Nearby");

		private final String label;

		CannonTrigger(String label) { this.label = label; }

		@Override
		public String toString() { return label; }
	}

	enum CombatStat
	{
		SUPPLIES(null), STRENGTH(Skill.STRENGTH), ATTACK(Skill.ATTACK), DEFENCE(Skill.DEFENCE),
		RANGED(Skill.RANGED), MAGIC(Skill.MAGIC);

		/** Null for {@link #SUPPLIES}, which watches whatever the carried supplies boost. */
		final Skill skill;

		CombatStat(Skill skill) { this.skill = skill; }

		@Override
		public String toString() { return skill == null ? "From supplies" : skill.getName(); }
	}

	@ConfigSection(name = "Display", description = "", position = 0)
	String display = "display";

	@ConfigSection(name = "Combat boost", description = "", position = 1, closedByDefault = true)
	String boost = "boost";

	@ConfigSection(name = "Poison protection", description = "", position = 2, closedByDefault = true)
	String poison = "poison";

	@ConfigSection(name = "Prayer", description = "", position = 3, closedByDefault = true)
	String prayer = "prayer";

	@ConfigSection(name = "Health", description = "", position = 4, closedByDefault = true)
	String health = "health";

	@ConfigSection(name = "Cannon", description = "", position = 5, closedByDefault = true)
	String cannon = "cannon";

	@ConfigSection(name = "Drops", description = "", position = 6, closedByDefault = true)
	String drops = "drops";

	@ConfigSection(name = "Goading potion", description = "", position = 7, closedByDefault = true)
	String goading = "goading";

	@ConfigSection(name = "Prayer regeneration", description = "", position = 8, closedByDefault = true)
	String prayerRegeneration = "prayerRegeneration";

	@ConfigSection(name = "Slayer bracelet", description = "Expeditious bracelet and bracelet of slaughter.", position = 9, closedByDefault = true)
	String bracelet = "bracelet";

	@ConfigSection(name = "Slayer task", description = "", position = 10, closedByDefault = true)
	String slayer = "slayer";

	@ConfigSection(name = "Idle", description = "", position = 11, closedByDefault = true)
	String idle = "idle";

	@ConfigItem(keyName = "dimEnabled", name = "Dim screen", description = "", section = display, position = 0)
	default boolean dimEnabled() { return true; }

	@Range(min = 0, max = 255)
	@ConfigItem(keyName = "dimOpacity", name = "Dim opacity", description = "0 is clear; 255 is opaque.", section = display, position = 1)
	default int dimOpacity() { return 200; }

	@Range(min = 0, max = 255)
	@ConfigItem(keyName = "alertOpacity", name = "Alert opacity", description = "0 is clear; 255 is opaque.", section = display, position = 2)
	default int alertOpacity() { return 100; }

	@Range(min = 300, max = 3000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(keyName = "flashPeriod", name = "Flash interval", description = "Time for one full flash cycle.", section = display, position = 3)
	default int flashPeriod() { return 1200; }

	@Range(min = 1, max = 10)
	@Units(Units.SECONDS)
	@ConfigItem(keyName = "alertRotation", name = "Cycle alerts every", description = "When more than one alert is active.", section = display, position = 4)
	default int alertRotation() { return 3; }

	@Range(min = 12, max = 48)
	@ConfigItem(keyName = "textSize", name = "Text size", description = "", section = display, position = 5)
	default int textSize() { return 24; }

	@ConfigItem(keyName = "showAlertText", name = "Show alert text", description = "", section = display, position = 6)
	default boolean showAlertText() { return true; }

	@ConfigItem(keyName = "pauseKey", name = "Pause hotkey", description = "Pauses the overlay and notifications.", section = display, position = 7)
	default Keybind pauseKey() { return new Keybind(KeyEvent.VK_D, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK); }

	@ConfigItem(keyName = "boostMode", name = "Alert when", description = "Off, always, or only while you carry potions or hearts that boost the stat.", section = boost, position = 0)
	default Trigger boostMode() { return Trigger.SUPPLIES; }

	@ConfigItem(keyName = "combatStat", name = "Stat", description = "From supplies watches every stat boosted by the potions or hearts you carry.", section = boost, position = 1)
	default CombatStat combatStat() { return CombatStat.SUPPLIES; }

	@Range(min = 0, max = 30)
	@ConfigItem(keyName = "boostLevelsAbove", name = "Alert at or below", description = "Levels above your base level. For example, 5 alerts once the boost has worn down to +5 or less.", section = boost, position = 2)
	default int boostLevelsAbove() { return 10; }

	@ConfigItem(keyName = "boostColor", name = "Colour", description = "", section = boost, position = 3)
	default Color boostColor() { return new Color(60, 210, 100); }

	@ConfigItem(keyName = "boostStyle", name = "Style", description = "", section = boost, position = 4)
