	@ConfigItem(keyName = "poisonMode", name = "Alert when", description = "Off, always, or only while you carry an antipoison, antidote or anti-venom.", section = poison, position = 0)
	default Trigger poisonMode() { return Trigger.SUPPLIES; }

	@ConfigItem(keyName = "poisonOnlyWhenPoisoned", name = "Only when poisoned", description = "Alerts only while you are poisoned or venomed. When off, alerts whenever poison protection is missing.", section = poison, position = 1)
