package com.afkingtoolkit;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class AfkingToolkitOverlay extends Overlay
{
	private final Client client;
	private final AfkingToolkitPlugin plugin;
	private final AfkingToolkitConfig config;

	@Inject
	AfkingToolkitOverlay(Client client, AfkingToolkitPlugin plugin, AfkingToolkitConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ToolkitDisplay display = plugin.getDisplay();
		if (!display.visible || client.getGameState() != GameState.LOGGED_IN) { return null; }
		long elapsed = plugin.elapsedMillis();
		ToolkitDisplay.Alert alert = display.activeAlert(elapsed, config.alertRotation());
		Color color;
		int opacity;
		if (alert == null)
		{
			if (!config.dimEnabled() || System.nanoTime() < display.undimUntilNanos) { return null; }
			color = Color.BLACK;
			opacity = config.dimOpacity();
		}
		else
		{
			int flashPeriod = Math.max(300, config.flashPeriod());
			if (alert.style == AfkingToolkitConfig.AlertStyle.FLASH
				&& elapsed % flashPeriod >= flashPeriod / 2)
			{
				return null;
			}
			color = alert.color;
			opacity = config.alertOpacity();
		}
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, opacity))));
		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

package com.afkingtoolkit;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "AFKing Toolkit",
	description = "Dims the screen and alerts you when boosts, prayer, health, poison, cannon, drops, slayer bracelets or idling need attention",
	tags = {"afk", "idle", "alt", "combat", "cannon", "slayer", "notifications", "loot"}
)
public class AfkingToolkitPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(AfkingToolkitPlugin.class);

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private AfkingToolkitConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private AfkingToolkitOverlay overlay;
	@Inject private AfkingToolkitTextOverlay textOverlay;
	@Inject private KeyManager keyManager;
	@Inject private ItemManager itemManager;
	@Inject private Notifier notifier;

	private final GroundDrops groundDrops = new GroundDrops();
	private final PoisonProtection poison = new PoisonProtection();
	private final CannonActivity cannonActivity = new CannonActivity();
	private final IdleTracker idle = new IdleTracker();
	private int slayerCount = -1;
	private final Map<Integer, Set<Supply>> supplyCache = new HashMap<>();
	private Set<Supply> carried = Set.of();
	private Set<String> notified = Set.of();
	private volatile ToolkitDisplay display = ToolkitDisplay.HIDDEN;
	private volatile boolean running;
	private boolean paused;
	private volatile long alertStartedAt;
	private TileItem alertedDrop;
	private long pickupUndimUntil;

	private final HotkeyListener pauseListener = new HotkeyListener(() -> config.pauseKey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(() ->
			{
				if (!running) { return; }
				paused = !paused;
				refresh();
			});
		}
	};

	@Provides
	AfkingToolkitConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(AfkingToolkitConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		alertStartedAt = System.nanoTime();
		overlayManager.add(overlay);
		overlayManager.add(textOverlay);
		keyManager.registerKeyListener(pauseListener);
		clientThread.invoke(() ->
		{
			if (!running) { return; }
			paused = false;
			clearPickupDelay();
			poison.clear();
			cannonActivity.clear();
			idle.clear();
			slayerCount = -1;
			groundDrops.configure(config.dropNames());
			scanDrops();
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		display = ToolkitDisplay.HIDDEN;
		overlayManager.remove(overlay);
		overlayManager.remove(textOverlay);
		keyManager.unregisterKeyListener(pauseListener);
		clientThread.invoke(() ->
		{
			if (running) { return; }
			groundDrops.clear();
			poison.clear();
			clearPickupDelay();
			cannonActivity.clear();
			idle.clear();
			slayerCount = -1;
			notified = Set.of();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AfkingToolkitConfig.GROUP.equals(event.getGroup())) { return; }
		clientThread.invoke(() ->
		{
			if (!running) { return; }
			if ("dropNames".equals(event.getKey()) || "dropsEnabled".equals(event.getKey()))
			{
				groundDrops.configure(config.dropNames());
				clearPickupDelay();
				scanDrops();
			}
			if ("pickupDimDelay".equals(event.getKey())) { pickupUndimUntil = 0; }
			refresh();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			scanDrops();
			refresh();
		}
		else
		{
			display = ToolkitDisplay.HIDDEN;
			groundDrops.clear();
			cannonActivity.clear();
			clearPickupDelay();
			if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
			{
				poison.clear();
				idle.clear();
				slayerCount = -1;
				notified = Set.of();
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The task count reaches zero when a task is finished or skipped.
		int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (slayerCount > 0 && count == 0 && config.slayerPause()) { paused = true; }
		slayerCount = count;
		refresh();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		boolean gained = idle.xpChanged(event.getSkill(), event.getXp(), client.getTickCount());
		if (gained || event.getSkill() == Skill.HITPOINTS || event.getSkill() == Skill.PRAYER
			|| Supply.boostedBy(event.getSkill()) != null)
		{
			refresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN) { refresh(); }
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.POISON || event.getVarpId() == VarPlayerID.DROPCANNON
			|| event.getVarpId() == VarPlayerID.ROCKTHROWER || event.getVarpId() == VarPlayerID.OWNEDMCANNON
			|| event.getVarbitId() == VarbitID.MCANNON_DECAYED
			|| event.getVarbitId() == VarbitID.GOADING_POTION_TIMER
			|| event.getVarbitId() == VarbitID.PRAYER_REGENERATION_POTION_TIMER)
		{
			refresh();
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		if (config.dropsEnabled() && groundDrops.isConfigured()
			&& groundDrops.add(event.getItem(), event.getTile(), itemName(event.getItem().getId())))
		{
			refresh();
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		if (!groundDrops.remove(event.getItem())) { return; }
		if (running && !paused && config.dropsEnabled() && event.getItem() == alertedDrop)
		{
			int delay = config.pickupDimDelay();
			pickupUndimUntil = delay <= 0 ? 0 : System.nanoTime() + delay * 1_000_000_000L;
		}
		refresh();
	}

	private void clearPickupDelay()
	{
		alertedDrop = null;
		pickupUndimUntil = 0;
	}

	private void scanDrops()
	{
		groundDrops.clear();
		if (!config.dropsEnabled() || !groundDrops.isConfigured() || client.getGameState() != GameState.LOGGED_IN) { return; }
		WorldView world = client.getTopLevelWorldView();
		if (world == null) { return; }
		for (Tile[][] plane : world.getScene().getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null || tile.getGroundItems() == null) { continue; }
					for (TileItem item : tile.getGroundItems()) { groundDrops.add(item, tile, itemName(item.getId())); }
				}
			}
		}
	}

	private void refresh()
	{
		Player player = client.getLocalPlayer();
		if (!running || client.getGameState() != GameState.LOGGED_IN || player == null
			|| client.getBoostedSkillLevel(Skill.HITPOINTS) <= 0 || paused)
		{
			display = ToolkitDisplay.HIDDEN;
			cannonActivity.clear();
			clearPickupDelay();
			return;
		}

		int tick = client.getTickCount();
		carried = carriedSupplies();
		List<ToolkitDisplay.Alert> alerts = new ArrayList<>();
		List<String> status = new ArrayList<>();
		int health = client.getBoostedSkillLevel(Skill.HITPOINTS);
		if (config.healthMode() != AfkingToolkitConfig.Trigger.OFF)
		{
			if (health <= config.healthThreshold() && triggered(config.healthMode(), Supply.FOOD))
			{
				alerts.add(new ToolkitDisplay.Alert("Restore health", config.healthColor(), config.healthStyle(), config.healthNotification()));
			}
			if (config.showHealth()) { status.add("HP: " + health); }
		}

		int prayer = client.getBoostedSkillLevel(Skill.PRAYER);
		if (config.prayerMode() != AfkingToolkitConfig.Trigger.OFF)
		{
			if (prayer <= config.prayerThreshold() && triggered(config.prayerMode(), Supply.PRAYER))
			{
				alerts.add(new ToolkitDisplay.Alert("Restore prayer", config.prayerColor(), config.prayerStyle(), config.prayerNotification()));
			}
			if (config.showPrayer()) { status.add("Prayer: " + prayer); }
		}

		poison.update(client.getVarpValue(VarPlayerID.POISON), tick);
		if (config.poisonMode() != AfkingToolkitConfig.Trigger.OFF)
		{
			boolean needed = config.poisonOnlyWhenPoisoned() ? poison.isPoisoned() : !poison.isProtected();
			if (needed && triggered(config.poisonMode(), Supply.ANTIPOISON))
			{
				String message = poison.isVenomed() ? "Cure venom" : poison.isPoisoned() ? "Cure poison" : "Drink anti-poison";
				alerts.add(new ToolkitDisplay.Alert(message, config.poisonColor(), config.poisonStyle(), config.poisonNotification()));
			}
			if (config.showPoison()) { status.add(poison.status(tick)); }
		}

		if (config.boostMode() != AfkingToolkitConfig.Trigger.OFF)
		{
			Skill chosen = config.combatStat().skill;
			List<Skill> watched = new ArrayList<>();
			boolean boostTriggered = true;
			if (chosen == null)
			{
				for (AfkingToolkitConfig.CombatStat stat : AfkingToolkitConfig.CombatStat.values())
				{
					if (stat.skill != null && carried.contains(Supply.boostedBy(stat.skill))) { watched.add(stat.skill); }
				}
			}
			else
			{
				watched.add(chosen);
				boostTriggered = triggered(config.boostMode(), Supply.boostedBy(chosen));
			}
			List<Skill> low = new ArrayList<>();
			for (Skill stat : watched)
			{
				int level = client.getBoostedSkillLevel(stat);
				if (level - client.getRealSkillLevel(stat) <= config.boostLevelsAbove()) { low.add(stat); }
				if (config.showBoost()) { status.add(stat.getName() + ": " + level); }
			}
			if (boostTriggered && !low.isEmpty())
			{
				String target = low.size() == 1 ? low.get(0).getName().toLowerCase(Locale.ROOT) : "combat stats";
				alerts.add(new ToolkitDisplay.Alert("Boost " + target,
					config.boostColor(), config.boostStyle(), config.boostNotification()));
			}
		}

		if (client.getVarbitValue(VarbitID.GOADING_POTION_TIMER) <= 0 && triggered(config.goadingMode(), Supply.GOADING))
		{
			alerts.add(new ToolkitDisplay.Alert("Drink goading potion", config.goadingColor(), config.goadingStyle(), config.goadingNotification()));
		}

		if (client.getVarbitValue(VarbitID.PRAYER_REGENERATION_POTION_TIMER) <= 0
			&& triggered(config.prayerRegenerationMode(), Supply.PRAYER_REGENERATION))
		{
			alerts.add(new ToolkitDisplay.Alert("Drink prayer regeneration",
				config.prayerRegenerationColor(), config.prayerRegenerationStyle(), config.prayerRegenerationNotification()));
		}

		Set<Supply> worn = supplies(itemId(client.getItemContainer(InventoryID.WORN), EquipmentInventorySlot.GLOVES.getSlotIdx()));
		if (!worn.contains(Supply.EXPEDITIOUS_BRACELET) && !worn.contains(Supply.SLAUGHTER_BRACELET)
			&& triggered(config.braceletMode(), Supply.EXPEDITIOUS_BRACELET, Supply.SLAUGHTER_BRACELET))
		{
			alerts.add(new ToolkitDisplay.Alert("Equip " + braceletName(), config.braceletColor(), config.braceletStyle(), config.braceletNotification()));
		}

		AfkingToolkitConfig.CannonTrigger cannonMode = config.cannonMode();
		boolean placed = client.getVarpValue(VarPlayerID.DROPCANNON) == 4;
		boolean watched = placed && (cannonMode == AfkingToolkitConfig.CannonTrigger.ANYWHERE
			|| cannonMode == AfkingToolkitConfig.CannonTrigger.NEARBY && player.getWorldLocation().distanceTo(
				WorldPoint.fromCoord(client.getVarpValue(VarPlayerID.OWNEDMCANNON))) <= config.cannonRange());
		int ammo = client.getVarpValue(VarPlayerID.ROCKTHROWER);
		boolean broken = client.getVarbitValue(VarbitID.MCANNON_DECAYED) == 1;
		if (watched)
		{
			if (broken && config.cannonRepairAlert())
			{
				alerts.add(new ToolkitDisplay.Alert("Repair cannon", config.cannonColor(), config.cannonStyle(), config.cannonNotification()));
			}
			else if (config.cannonAmmoAlert() && ammo <= config.cannonThreshold())
			{
				alerts.add(new ToolkitDisplay.Alert("Reload cannon", config.cannonColor(), config.cannonStyle(), config.cannonNotification()));
			}
			else if (!broken && ammo > 0 && cannonActivity.isInactive(client))
			{
				alerts.add(new ToolkitDisplay.Alert("Cannon inactive", config.cannonColor(), config.cannonStyle(), config.cannonNotification()));
			}
			if (config.showCannon()) { status.add(0, ToolkitDisplay.cannonText(config.cannonPrefix(), ammo)); }
		}
		if (!watched || broken || ammo <= 0) { cannonActivity.clear(); }

		if (config.idleEnabled() && idle.isIdle(tick, config.idleSeconds()))
		{
			alerts.add(new ToolkitDisplay.Alert("Idle", config.idleColor(), config.idleStyle(), config.idleNotification()));
		}

		TileItem drop = config.dropsEnabled()
			? groundDrops.nearest(player.getWorldLocation(), config.dropRange(), config.ownDropsOnly()) : null;
		alertedDrop = drop;
		if (drop != null)
		{
			alerts.add(0, new ToolkitDisplay.Alert("Pick up " + itemName(drop.getId()), config.dropColor(), config.dropStyle(), config.dropNotification()));
		}
		ToolkitDisplay next = new ToolkitDisplay(true, alerts, status, pickupUndimUntil);
		if (!next.hasSameAlerts(display)) { alertStartedAt = System.nanoTime(); }
		display = next;
		notifyNewAlerts(alerts);
	}

	private boolean triggered(AfkingToolkitConfig.Trigger trigger, Supply... wanted)
	{
		switch (trigger)
		{
			case ALWAYS:
				return true;
			case SUPPLIES:
				for (Supply supply : wanted)
				{
					if (carried.contains(supply)) { return true; }
				}
				return false;
			default:
				return false;
		}
	}

	private String braceletName()
	{
		boolean expeditious = carried.contains(Supply.EXPEDITIOUS_BRACELET);
		boolean slaughter = carried.contains(Supply.SLAUGHTER_BRACELET);
		if (expeditious == slaughter) { return "slayer bracelet"; }
		return expeditious ? "expeditious bracelet" : "bracelet of slaughter";
	}

	private String itemName(int itemId)
	{
		ItemComposition item = itemManager.getItemComposition(itemId);
		return item == null ? null : Text.removeTags(item.getName());
	}

	private Set<Supply> carriedSupplies()
	{
		Set<Supply> result = EnumSet.noneOf(Supply.class);
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null) { return result; }
		for (Item item : inventory.getItems()) { result.addAll(supplies(item.getId())); }
		return result;
	}

	private static int itemId(ItemContainer container, int slot)
	{
		Item item = container == null ? null : container.getItem(slot);
		return item == null ? -1 : item.getId();
	}

	private Set<Supply> supplies(int itemId)
	{
		if (itemId <= 0) { return Set.of(); }
		return supplyCache.computeIfAbsent(itemId, id ->
		{
			ItemComposition item = itemManager.getItemComposition(id);
			// Noted items cannot be eaten, drunk or worn.
			if (item == null || item.getNote() != -1) { return Set.of(); }
			return Supply.classify(item.getName(), item.getInventoryActions());
		});
	}

	private void notifyNewAlerts(List<ToolkitDisplay.Alert> alerts)
	{
		// Notifications are sent when an alert starts, not on every tick it stays active.
		Set<String> active = new HashSet<>();
		for (ToolkitDisplay.Alert alert : alerts)
		{
			if (active.add(alert.message) && !notified.contains(alert.message) && alert.notification.isEnabled())
			{
				notifier.notify(alert.notification, alert.message);
			}
		}
		notified = active;
	}

	ToolkitDisplay getDisplay() { return display; }

	long elapsedMillis() { return (System.nanoTime() - alertStartedAt) / 1_000_000; }
}

package com.afkingtoolkit;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class AfkingToolkitTextOverlay extends Overlay
{
	private static final int WIDTH = 240;
	private static final int HEIGHT = 60;

	private final Client client;
	private final AfkingToolkitPlugin plugin;
	private final AfkingToolkitConfig config;
	private Font font;
	private int fontSize;

	@Inject
	AfkingToolkitTextOverlay(Client client, AfkingToolkitPlugin plugin, AfkingToolkitConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DETACHED);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ToolkitDisplay display = plugin.getDisplay();
		if (!display.visible) { return null; }
		ToolkitDisplay.Alert alert = display.activeAlert(plugin.elapsedMillis(), config.alertRotation());
		List<String> lines = alert == null ? display.status
			: config.showAlertText() ? List.of(alert.message) : List.of();
		if (lines.isEmpty()) { return null; }
		int size = config.textSize();
		if (font == null || fontSize != size)
		{
			fontSize = size;
			font = FontManager.getRunescapeBoldFont().deriveFont((float) Math.max(12, fontSize));
		}
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		if (getPreferredLocation() == null)
		{
			int x = (client.getCanvasWidth() - WIDTH) / 2;
			int y = (client.getCanvasHeight() - HEIGHT) / 2;
			graphics.translate(x - getBounds().x, y - getBounds().y);
			getBounds().setLocation(x, y);
		}
		int y = (HEIGHT - lines.size() * metrics.getHeight()) / 2 + metrics.getAscent();
		for (String line : lines)
		{
			int x = (WIDTH - metrics.stringWidth(line)) / 2;
			graphics.setColor(Color.BLACK);
			graphics.drawString(line, x + 1, y + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(line, x, y);
			y += metrics.getHeight();
		}
		// A fixed drag area keeps the midpoint stable when the text changes.
		return new Dimension(WIDTH, HEIGHT);
	}
}

package com.afkingtoolkit;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.Renderable;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;

class CannonActivity
{
	private GameObject observed;
	private int stoppedSince = -1;

	boolean isInactive(Client client)
	{
		GameObject cannon = findCannon(client);
		if (cannon == null)
		{
			clear();
			return false;
		}
		Renderable renderable = cannon.getRenderable();
		Animation animation = renderable instanceof DynamicObject ? ((DynamicObject) renderable).getAnimation() : null;
		if (renderable == null || (animation != null && animation.getId() != AnimationID.CANNON_LEAGUE03_IDLE))
		{
			clear();
			return false;
		}
		int tick = client.getTickCount();
		if (observed != cannon || stoppedSince < 0 || tick < stoppedSince)
		{
			observed = cannon;
			stoppedSince = tick;
		}
		// Allow the short gap between successive turning animations.
		return tick - stoppedSince >= 2;
	}

	private GameObject findCannon(Client client)
	{
		WorldView world = client.getTopLevelWorldView();
		if (world == null) { return null; }
		WorldPoint position = WorldPoint.fromCoord(client.getVarpValue(VarPlayerID.OWNEDMCANNON));
		if (position.getPlane() != world.getPlane()) { return null; }
		int x = position.getX() - world.getBaseX();
		int y = position.getY() - world.getBaseY();
		Tile[][] tiles = world.getScene().getTiles()[position.getPlane()];
		if (x < 0 || x >= tiles.length || y < 0 || y >= tiles[x].length) { return null; }
		Tile tile = tiles[x][y];
		if (tile == null) { return null; }
		for (GameObject object : tile.getGameObjects())
		{
			if (object != null && (object.getId() == ObjectID.DWARF_MULTICANNON1
				|| object.getId() == ObjectID.LEAGUE03_MULTICANNON_ACTIVE)
				&& object.getSceneMinLocation().getX() == x && object.getSceneMinLocation().getY() == y)
			{
				return object;
			}
		}
		return null;
	}

	void clear()
	{
		observed = null;
		stoppedSince = -1;
	}
}

package com.afkingtoolkit;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;

final class GroundDrops
{
	private final Map<TileItem, Tile> items = new IdentityHashMap<>();
	private Pattern names;

	/** Takes semicolon-separated item names, where * matches any run of characters. */
	void configure(String text)
	{
		List<String> globs = new ArrayList<>();
		for (String token : text.split("[;\\n]"))
		{
			String glob = token.trim();
			if (!glob.isEmpty()) { globs.add(toRegex(glob)); }
		}
		names = globs.isEmpty() ? null
			: Pattern.compile(String.join("|", globs), Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
		clear();
	}

	private static String toRegex(String glob)
	{
		String[] parts = glob.split("\\*", -1);
		StringBuilder regex = new StringBuilder("(?:");
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0) { regex.append(".*"); }
			if (!parts[i].isEmpty()) { regex.append(Pattern.quote(parts[i])); }
		}
		return regex.append(')').toString();
	}

	boolean isConfigured() { return names != null; }

	boolean matches(String name) { return names != null && name != null && names.matcher(name.trim()).matches(); }

	boolean add(TileItem item, Tile tile, String name)
	{
		if (!matches(name)) { return false; }
		items.put(item, tile);
		return true;
	}

	boolean remove(TileItem item) { return items.remove(item) != null; }

	void clear() { items.clear(); }

	TileItem nearest(WorldPoint player, int range, boolean ownOnly)
	{
		TileItem nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (Map.Entry<TileItem, Tile> entry : items.entrySet())
		{
			TileItem item = entry.getKey();
			int owner = item.getOwnership();
			boolean mine = owner == TileItem.OWNERSHIP_SELF || owner == TileItem.OWNERSHIP_GROUP;
			if (item.getQuantity() <= 0 || (ownOnly && !mine) || (item.isPrivate() && !mine)) { continue; }
			int distance = player.distanceTo(entry.getValue().getWorldLocation());
			if (distance <= range && (distance < nearestDistance
				|| (distance == nearestDistance && nearest != null && item.getId() < nearest.getId())))
			{
				nearest = item;
				nearestDistance = distance;
			}
		}
		return nearest;
	}
}

package com.afkingtoolkit;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

final class IdleTracker
{
	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private int lastGainTick = -1;

	boolean xpChanged(Skill skill, int value, int tick)
	{
		Integer previous = xp.put(skill, value);
		// The first value seen for a skill after login is a baseline, not a gain.
		if (previous == null || value <= previous) { return false; }
		lastGainTick = tick;
		return true;
	}

	boolean isIdle(int tick, int seconds)
	{
		if (lastGainTick < 0 || tick < lastGainTick) { return false; }
		int ticks = (Math.max(1, seconds) * 1000 + 599) / 600;
		return tick - lastGainTick >= ticks;
	}

	void clear()
	{
		xp.clear();
		lastGainTick = -1;
	}
}

package com.afkingtoolkit;

final class PoisonProtection
{
	private static final int POISON_TICKS = 30;
	private int value;
	private int nextTick = -1;

	void update(int newValue, int tick)
	{
		if (newValue != value || nextTick < 0)
		{
			if (newValue == 0) { nextTick = -1; }
			else if (nextTick <= tick) { nextTick = tick + POISON_TICKS; }
			value = newValue;
		}
	}

	boolean isProtected() { return value < 0; }

	boolean isPoisoned() { return value > 0; }

	boolean isVenomed() { return value >= 1_000_000; }

	String status(int tick)
	{
		if (!isProtected()) { return value > 0 ? "Poison: affected" : "Poison: unprotected"; }
		boolean venomProtection = value < -38;
		int remainingSteps = venomProtection ? -(value + 38) : -value;
		int ticks = Math.max(0, nextTick - tick + (remainingSteps - 1) * POISON_TICKS);
		int seconds = (ticks * 3 + 4) / 5;
		return (venomProtection ? "Anti-venom: " : "Anti-poison: ")
			+ seconds / 60 + ":" + String.format("%02d", seconds % 60);
	}

	void clear()
	{
		value = 0;
		nextTick = -1;
	}
}

package com.afkingtoolkit;

import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.Skill;

enum Supply
{
	FOOD, PRAYER, ANTIPOISON, ATTACK, STRENGTH, DEFENCE, RANGED, MAGIC,
	GOADING, PRAYER_REGENERATION, EXPEDITIOUS_BRACELET, SLAUGHTER_BRACELET;

	private static final Set<String> PRAYER_NAMES = Set.of(
		"prayer potion", "super restore", "blighted super restore", "sanfew serum", "prayer mix",
		"super restore mix", "ancient brew", "forgotten brew");
	private static final Set<String> ATTACK_NAMES = Set.of(
		"attack potion", "super attack", "divine super attack potion", "combat potion", "super combat potion",
		"divine super combat potion", "zamorak brew", "attack mix", "superattack mix", "combat mix", "zamorak mix");
	private static final Set<String> STRENGTH_NAMES = Set.of(
		"strength potion", "super strength", "divine super strength potion", "combat potion", "super combat potion",
		"divine super combat potion", "zamorak brew", "strength mix", "super str. mix", "combat mix", "zamorak mix");
	private static final Set<String> DEFENCE_NAMES = Set.of(
		"defence potion", "super defence", "divine super defence potion", "super combat potion",
		"divine super combat potion", "saradomin brew", "bastion potion", "divine bastion potion", "battlemage potion",
		"divine battlemage potion", "defence mix", "super def. mix");
	private static final Set<String> RANGED_NAMES = Set.of(
		"ranging potion", "divine ranging potion", "bastion potion", "divine bastion potion", "ranging mix");
	private static final Set<String> MAGIC_NAMES = Set.of(
		"magic potion", "divine magic potion", "battlemage potion", "divine battlemage potion", "magic mix",
		"magic essence", "imbued heart", "saturated heart", "ancient brew", "forgotten brew");

	/** The supply that boosts a combat stat, or null for stats no tracked supply boosts. */
	static Supply boostedBy(Skill skill)
	{
		switch (skill)
		{
			case ATTACK: return ATTACK;
			case STRENGTH: return STRENGTH;
			case DEFENCE: return DEFENCE;
			case RANGED: return RANGED;
			case MAGIC: return MAGIC;
			default: return null;
		}
	}

	static Set<Supply> classify(String itemName, String[] actions)
	{
		Set<Supply> supplies = EnumSet.noneOf(Supply.class);
		if (itemName == null) { return supplies; }
		// Potions share a base name across doses, e.g. "Prayer potion(3)".
		String name = itemName.toLowerCase(Locale.ROOT).replaceFirst("\\(\\d+\\)$", "").trim();
		if (hasAction(actions, "Eat") || name.equals("saradomin brew")) { supplies.add(FOOD); }
		if (PRAYER_NAMES.contains(name)) { supplies.add(PRAYER); }
		if (name.contains("antipoison") || name.contains("anti-poison") || name.contains("antidote")
			|| name.contains("anti-venom") || name.equals("sanfew serum"))
		{
			supplies.add(ANTIPOISON);
		}
		if (ATTACK_NAMES.contains(name)) { supplies.add(ATTACK); }
		if (STRENGTH_NAMES.contains(name)) { supplies.add(STRENGTH); }
		if (DEFENCE_NAMES.contains(name)) { supplies.add(DEFENCE); }
		if (RANGED_NAMES.contains(name)) { supplies.add(RANGED); }
		if (MAGIC_NAMES.contains(name)) { supplies.add(MAGIC); }
		if (name.equals("goading potion")) { supplies.add(GOADING); }
		if (name.equals("prayer regeneration potion")) { supplies.add(PRAYER_REGENERATION); }
		if (name.equals("expeditious bracelet")) { supplies.add(EXPEDITIOUS_BRACELET); }
		if (name.equals("bracelet of slaughter")) { supplies.add(SLAUGHTER_BRACELET); }
		return supplies;
	}

	private static boolean hasAction(String[] actions, String action)
	{
		if (actions == null) { return false; }
		for (String candidate : actions)
		{
			if (action.equals(candidate)) { return true; }
		}
		return false;
	}
}

package com.afkingtoolkit;

import java.awt.Color;
import java.util.List;
import net.runelite.client.config.Notification;

final class ToolkitDisplay
{
	static final ToolkitDisplay HIDDEN = new ToolkitDisplay(false, List.of(), List.of());
	final boolean visible;
	final List<Alert> alerts;
	final List<String> status;
	final long undimUntilNanos;

	ToolkitDisplay(boolean visible, List<Alert> alerts, List<String> status)
	{
		this(visible, alerts, status, 0);
	}

	ToolkitDisplay(boolean visible, List<Alert> alerts, List<String> status, long undimUntilNanos)
	{
		this.visible = visible;
		this.alerts = List.copyOf(alerts);
		this.status = List.copyOf(status);
		this.undimUntilNanos = undimUntilNanos;
	}

	Alert activeAlert(long elapsedMillis, int rotationSeconds)
	{
		if (alerts.isEmpty()) { return null; }
		int index = (int) ((Math.max(0, elapsedMillis) / (Math.max(1, rotationSeconds) * 1000L)) % alerts.size());
		return alerts.get(index);
	}

	boolean hasSameAlerts(ToolkitDisplay other)
	{
		if (alerts.size() != other.alerts.size()) { return false; }
		for (int i = 0; i < alerts.size(); i++)
		{
			if (!alerts.get(i).message.equals(other.alerts.get(i).message)) { return false; }
		}
		return true;
	}

	static String cannonText(String prefix, int ammo)
	{
		String label = prefix.trim();
		return label.isEmpty() ? Integer.toString(ammo) : label + " " + ammo;
	}

	static final class Alert
	{
		final String message;
		final Color color;
		final AfkingToolkitConfig.AlertStyle style;
		final Notification notification;

		Alert(String message, Color color, AfkingToolkitConfig.AlertStyle style)
		{
			this(message, color, style, Notification.OFF);
		}

		Alert(String message, Color color, AfkingToolkitConfig.AlertStyle style, Notification notification)
		{
			this.message = message;
			this.color = color;
			this.style = style;
			this.notification = notification;
		}
	}
}

