	@Test
	public void nearbyCannonModeIgnoresADistantCannon()
	{
		when(config.cannonMode()).thenReturn(AfkingToolkitConfig.CannonTrigger.NEARBY);
		when(config.cannonRange()).thenReturn(10);
		when(client.getVarpValue(VarPlayerID.DROPCANNON)).thenReturn(4);
		when(client.getVarpValue(VarPlayerID.OWNEDMCANNON)).thenReturn((3200 << 14) | 3210);
