package com.afkingtoolkit;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayLayer;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OverlayRenderingTest
{
	private final Client client = mock(Client.class);
	private final AfkingToolkitPlugin plugin = mock(AfkingToolkitPlugin.class);
	private final AfkingToolkitConfig config = new AfkingToolkitConfig() { };
	private final AfkingToolkitOverlay overlay = new AfkingToolkitOverlay(client, plugin, config);

	@Before
	public void setUp()
	{
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getCanvasWidth()).thenReturn(100);
		when(client.getCanvasHeight()).thenReturn(100);
	}

	@Test
	public void idleScreenIsDimmed()
	{
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(), List.of()));
		Color pixel = render();
		assertEquals(55, pixel.getRed());
		assertEquals(55, pixel.getGreen());
		assertEquals(55, pixel.getBlue());
	}

	@Test
	public void pickupDelayKeepsTheScreenClearUntilItsDeadline()
	{
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(), List.of(), System.nanoTime() + 3_000_000_000L));
		assertEquals(Color.WHITE, render());
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(), List.of(), System.nanoTime() - 1));
		assertEquals(55, render().getRed());
	}

	@Test
	public void otherAlertsStillRenderDuringPickupDelay()
	{
		ToolkitDisplay.Alert alert = new ToolkitDisplay.Alert("Restore health", Color.RED, AfkingToolkitConfig.AlertStyle.SOLID);
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(alert), List.of(), System.nanoTime() + 3_000_000_000L));
		Color pixel = render();
		assertEquals(255, pixel.getRed());
		assertEquals(155, pixel.getGreen());
	}

	@Test
	public void solidAlertReplacesTheDim()
	{
		setAlert(AfkingToolkitConfig.AlertStyle.SOLID);
		when(plugin.elapsedMillis()).thenReturn(1000L);
		Color pixel = render();
		assertEquals(255, pixel.getRed());
		assertEquals(155, pixel.getGreen());
	}

	@Test
	public void flashOffPhaseLeavesTheGameClear()
	{
		setAlert(AfkingToolkitConfig.AlertStyle.FLASH);
		when(plugin.elapsedMillis()).thenReturn(1000L);
		assertEquals(Color.WHITE, render());
		when(plugin.elapsedMillis()).thenReturn(1200L);
		assertEquals(155, render().getGreen());
	}

	@Test
	public void textStaysWhiteAboveDimmingAndSolidAlerts()
	{
		when(client.getCanvasWidth()).thenReturn(800);
		when(client.getCanvasHeight()).thenReturn(600);
		AfkingToolkitTextOverlay text = new AfkingToolkitTextOverlay(client, plugin, config);
		ToolkitDisplay.Alert alert = new ToolkitDisplay.Alert("Restore health", Color.RED, AfkingToolkitConfig.AlertStyle.SOLID);
		for (List<ToolkitDisplay.Alert> alerts : List.of(List.<ToolkitDisplay.Alert>of(), List.of(alert)))
		{
			when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, alerts, List.of("30")));
			BufferedImage image = new BufferedImage(800, 600, BufferedImage.TYPE_INT_RGB);
			for (OverlayLayer layer : OverlayLayer.values())
			{
				Graphics2D graphics = image.createGraphics();
				try
				{
					if (layer == text.getLayer()) { text.render(graphics); }
					if (layer == overlay.getLayer()) { overlay.render(graphics); }
				}
				finally { graphics.dispose(); }
			}
			boolean hasWhiteText = false;
			for (int y = 270; y < 330; y++)
			{
				for (int x = 280; x < 520; x++)
				{
					hasWhiteText |= image.getRGB(x, y) == Color.WHITE.getRGB();
				}
			}
			assertTrue("Text should remain white above the screen tint", hasWhiteText);
			text.getBounds().setLocation(0, 0);
		}
	}

	@Test
	public void loginAndPausedStatesNeverDim()
	{
		when(plugin.getDisplay()).thenReturn(ToolkitDisplay.HIDDEN);
		assertEquals(Color.WHITE, render());
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(), List.of()));
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		assertEquals(Color.WHITE, render());
	}

	private void setAlert(AfkingToolkitConfig.AlertStyle style)
	{
		ToolkitDisplay.Alert alert = new ToolkitDisplay.Alert("Drink anti-poison", Color.RED, style);
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(alert), List.of()));
	}

	private Color render()
	{
		BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(Color.WHITE);
			graphics.fillRect(0, 0, 100, 100);
			overlay.render(graphics);
			return new Color(image.getRGB(50, 50));
		}
		finally { graphics.dispose(); }
	}
}

package com.afkingtoolkit;

import org.junit.Test;
import static org.junit.Assert.*;

public class PoisonProtectionTest
{
	@Test
	public void onlyImmunityClearsTheWarning()
	{
		PoisonProtection protection = new PoisonProtection();
		for (int value : new int[] {0, 5, 1000000})
		{
			protection.update(value, 10);
			assertFalse(protection.isProtected());
		}
		protection.update(-1, 10);
		assertTrue(protection.isProtected());
		protection.update(0, 40);
		assertFalse(protection.isProtected());
	}

	@Test
	public void countdownKeepsTheObservedPoisonTickPhase()
	{
		PoisonProtection protection = new PoisonProtection();
		protection.update(-2, 10);
		assertEquals("Anti-poison: 0:36", protection.status(10));
		assertEquals("Anti-poison: 0:30", protection.status(20));
		protection.update(-1, 40);
		assertEquals("Anti-poison: 0:18", protection.status(40));
	}

	@Test
	public void antivenomTransitionsToAntipoisonWithoutAnAlert()
	{
		PoisonProtection protection = new PoisonProtection();
		protection.update(-39, 10);
		assertEquals("Anti-venom: 0:18", protection.status(10));
		protection.update(-38, 40);
		assertTrue(protection.isProtected());
		assertEquals("Anti-poison: 11:24", protection.status(40));
		protection.clear();
		assertFalse(protection.isProtected());
	}
}

package com.afkingtoolkit;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class SupplyTest
{
	@Test
	public void dosesShareTheirBaseName()
	{
		assertEquals(Set.of(Supply.PRAYER), Supply.classify("Prayer potion(1)", null));
		assertEquals(Set.of(Supply.PRAYER), Supply.classify("Super restore(4)", null));
		assertEquals(Set.of(Supply.GOADING), Supply.classify("Goading potion(2)", null));
		assertEquals(Set.of(Supply.PRAYER_REGENERATION), Supply.classify("Prayer regeneration potion(4)", null));
	}

	@Test
	public void everyPoisonCureCounts()
	{
		for (String name : new String[]{"Antipoison(4)", "Superantipoison(3)", "Antidote+(2)", "Antidote++(1)",
			"Anti-venom(4)", "Anti-venom+(4)", "Extended anti-venom+(4)", "Anti-poison supermix(2)"})
		{
			assertTrue(name, Supply.classify(name, null).contains(Supply.ANTIPOISON));
		}
		assertTrue(Supply.classify("Sanfew serum(4)", null).containsAll(Set.of(Supply.ANTIPOISON, Supply.PRAYER)));
		assertTrue(Supply.classify("Antifire potion(4)", null).isEmpty());
	}

	@Test
	public void boostsMatchTheStatsTheyRaise()
	{
		assertEquals(EnumSet.of(Supply.ATTACK, Supply.STRENGTH, Supply.DEFENCE),
			Supply.classify("Divine super combat potion(4)", null));
		assertEquals(EnumSet.of(Supply.RANGED, Supply.DEFENCE), Supply.classify("Bastion potion(4)", null));
		assertEquals(Set.of(Supply.MAGIC), Supply.classify("Imbued heart", null));
		assertEquals(Set.of(Supply.MAGIC), Supply.classify("Saturated heart", null));
		assertEquals(Supply.MAGIC, Supply.boostedBy(Skill.MAGIC));
		assertEquals(Supply.STRENGTH, Supply.boostedBy(Skill.STRENGTH));
		assertNull(Supply.boostedBy(Skill.HITPOINTS));
	}

	@Test
	public void foodIsAnythingYouCanEat()
	{
		assertEquals(Set.of(Supply.FOOD), Supply.classify("Shark", new String[]{"Eat", null, null, null, "Drop"}));
		assertTrue(Supply.classify("Saradomin brew(4)", null).contains(Supply.FOOD));
		assertTrue(Supply.classify("Raw shark", new String[]{null, null, null, null, "Drop"}).isEmpty());
	}

	@Test
	public void recognisesSlayerBracelets()
	{
		assertEquals(Set.of(Supply.EXPEDITIOUS_BRACELET), Supply.classify("Expeditious bracelet", null));
		assertEquals(Set.of(Supply.SLAUGHTER_BRACELET), Supply.classify("Bracelet of slaughter", null));
	}
}

package com.afkingtoolkit;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TextOverlayTest
{
	private final Client client = mock(Client.class);
	private final AfkingToolkitPlugin plugin = mock(AfkingToolkitPlugin.class);
	private final AfkingToolkitTextOverlay overlay = new AfkingToolkitTextOverlay(client, plugin, new AfkingToolkitConfig() { });

	@Test
	public void differentMessagesStayAtTheCanvasCenter()
	{
		assertCentered(List.of("30"), 800, 600, 400, 300);
		assertCentered(List.of("Drink anti-poison"), 800, 600, 400, 300);
		assertCentered(List.of("Pick up a very long item name"), 800, 600, 400, 300);
		assertCentered(List.of("30", "Prayer: 99", "Strength: 118"), 800, 600, 400, 300);
	}

	@Test
	public void defaultCenterFollowsCanvasResize()
	{
		assertCentered(List.of("30"), 800, 600, 400, 300);
		assertCentered(List.of("30"), 1000, 700, 500, 350);
	}

	@Test
	public void draggedMessagesKeepTheirMidpoint()
	{
		overlay.setPreferredLocation(new Point(100, 80));
		overlay.getBounds().setLocation(100, 80);
		assertCentered(List.of("30"), 800, 600, 220, 110);
		assertCentered(List.of("Drink anti-poison"), 800, 600, 220, 110);
	}

	private void assertCentered(List<String> lines, int width, int height, int centerX, int centerY)
	{
		when(client.getCanvasWidth()).thenReturn(width);
		when(client.getCanvasHeight()).thenReturn(height);
		when(plugin.getDisplay()).thenReturn(new ToolkitDisplay(true, List.of(), lines));
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.translate(overlay.getBounds().x, overlay.getBounds().y);
			Dimension size = overlay.render(graphics);
			overlay.getBounds().setSize(size);
			assertEquals(centerX, overlay.getBounds().getCenterX(), 0.5);
			assertEquals(centerY, overlay.getBounds().getCenterY(), 0.5);
			int left = width, right = 0, top = height, bottom = 0;
			for (int y = 0; y < height; y++)
			{
				for (int x = 0; x < width; x++)
				{
					if ((image.getRGB(x, y) >>> 24) == 0) { continue; }
					left = Math.min(left, x);
					right = Math.max(right, x);
					top = Math.min(top, y);
					bottom = Math.max(bottom, y);
				}
			}
			assertTrue(left < right);
			assertEquals(centerX, (left + right) / 2.0, 3);
			assertEquals(centerY, (top + bottom) / 2.0, 6);
		}
		finally { graphics.dispose(); }
	}
}

package com.afkingtoolkit;

import java.awt.Color;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class ToolkitDisplayTest
{
	@Test
	public void blankPrefixReallyShowsOnlyTheCount()
	{
		assertEquals("30", ToolkitDisplay.cannonText("", 30));
		assertEquals("0", ToolkitDisplay.cannonText("  ", 0));
		assertEquals("Ammo: 60", ToolkitDisplay.cannonText("Ammo:", 60));
	}

	@Test
	public void simultaneousAlertsEachGetAFullTurn()
	{
		ToolkitDisplay.Alert prayer = new ToolkitDisplay.Alert("Restore prayer", Color.CYAN, AfkingToolkitConfig.AlertStyle.FLASH);
		ToolkitDisplay.Alert drop = new ToolkitDisplay.Alert("Pick up Coins", Color.YELLOW, AfkingToolkitConfig.AlertStyle.SOLID);
		ToolkitDisplay display = new ToolkitDisplay(true, List.of(prayer, drop), List.of());
		assertSame(prayer, display.activeAlert(0, 3));
		assertSame(prayer, display.activeAlert(2999, 3));
		assertSame(drop, display.activeAlert(3000, 3));
		assertSame(prayer, display.activeAlert(6000, 3));
		assertNull(ToolkitDisplay.HIDDEN.activeAlert(0, 3));
	}
}
